 SELECT p.prosrc INTO guard_source FROM pg_proc p WHERE p.oid='secureshop_agents.guard_bound_tool_registry_upgrade()'::regprocedure;
 IF guard_source IS NULL OR encode(sha256(convert_to(guard_source,'UTF8')),'hex')<>old_guard_sha256
 OR array_length(string_to_array(guard_source,old_edge),1)<>2
 OR array_length(string_to_array(guard_source,v36_branch),1)<>2
 OR array_length(string_to_array(guard_source,denial_anchor),1)<>2 THEN
  RAISE EXCEPTION 'Expected v36 registry guard unavailable' USING ERRCODE='55000';
 END IF;
 guard_source:=replace(guard_source,old_edge,old_edge||E'\n'||new_edges);
 guard_source:=replace(guard_source,v36_branch,v37_branch||v36_branch);
 guard_source:=replace(guard_source,denial_anchor,E'\n END IF;'||denial_anchor);
 IF encode(sha256(convert_to(guard_source,'UTF8')),'hex')<>upgraded_guard_sha256 THEN RAISE EXCEPTION 'Registration registry guard checksum mismatch' USING ERRCODE='55000'; END IF;
 EXECUTE format('CREATE OR REPLACE FUNCTION secureshop_agents.guard_bound_tool_registry_upgrade() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,secureshop_agents AS %L',guard_source);
